<form class="nxmt-panel" data-nxmt-api="password"><h2>生成条件</h2><label>プリセット<select data-password-preset><option value="custom">カスタム</option><option value="simple">かんたん（12文字・英数字）</option><option value="normal" selected>通常（20文字・英数字と記号）</option><option value="strong">強め（32文字）</option><option value="maximum">最大（64文字）</option></select></label><div class="nxmt-fields"><label>文字数<input name="length" type="number" min="4" max="64" value="20"></label><label>生成個数<input name="count" type="number" min="1" max="8" value="4"></label></div><div class="nxmt-inline"><?php foreach (['upper' => '英大文字', 'lower' => '英小文字', 'digit' => '数字', 'symbols' => '記号'] as $key => $label): ?><label><input type="checkbox" name="<?= e($key) ?>" value="1" checked><?= e($label) ?></label><?php endforeach; ?></div><button type="submit">生成する</button><p role="status" data-api-status></p><textarea data-api-output rows="8" readonly aria-label="生成結果" autocomplete="off"></textarea><button type="button" class="secondary" data-copy-output>結果をコピー</button></form>
